/**
 * Get the total number of messages in the database matching this live view.
 */
[implicit_jscontext]
Promise countMessages();

/**
 * Get the number of unread messages in the database matching this live view.
 */
[implicit_jscontext]
Promise countUnreadMessages();

/**
 * Get the messages matching this live view from the database. Messages will
 * be sorted and grouped based on `sortColumn`, `sortDescending` and
 * `grouping`. Returns a promise resolving to an array of plain JS objects
 * containing the message properties.
 */
[implicit_jscontext]
Promise selectMessages();

/**
 * Get the messages matching this live view and the specified group. Returns
 * a promise resolving to an array of plain JS objects. Though the argument
 * is a string, JS type coercion means an integer group identifier can be
 * used, e.g. for date groups.
 */
[implicit_jscontext]
Promise selectMessagesInGroup(in AUTF8String group);
